{"implementation": "def solve(case):
    import math
    payload = case.get('payload', case)
    matrix = payload['matrix']
    if not matrix or len(matrix) == 0:
        raise ValueError('matrix is empty')
    n_rows = len(matrix)
    n_cols = len(matrix[0])
    for row in matrix:
        if len(row) != n_cols:
            raise ValueError('non-rectangular')
    doc_freq = [0] * n_cols
    for row in matrix:
        for j, val in enumerate(row):
            if val != 0:
                doc_freq[j] += 1
    idf = []
    for df in doc_freq:
        idf_val = math.log(1 + n_rows / (1 + df))
        idf.append(round(idf_val, 6))
    weighted_matrix = []
    for row in matrix:
        new_row = []
        for j, val in enumerate(row):
            if val != 0:
                w = val * idf[j]
                new_row.append(round(w, 6))
            else:
                new_row.append(0.0)
        weighted_matrix.append(new_row)
    row_degrees = [round(sum(row), 6) for row in weighted_matrix]
    return {
        'idf': idf,
        'weighted_matrix': weighted_matrix,
        'row_degrees': row_degrees
    }"}
